insert into public.kb (id, tag, title, text, keywords, active) values
  ('5eed0000-0000-4000-8000-000000000001', 'Livraison', 'Livraison Express et heure limite', 'La Livraison Express concerne Cotonou et Abomey-Calavi, 7 j/7, dimanche compris : une commande passée avant 20 h (heure du Bénin) est livrée le jour même, sinon le lendemain. Si vous payez à la livraison, c''est l''heure à laquelle nous confirmons votre commande sur WhatsApp qui compte, et non l''heure où vous l''avez passée. Ces délais s''appliquent hors force majeure (intempéries, grève, route coupée…). En cas de retard, nous vous prévenons sur WhatsApp ; vous pouvez alors annuler et être remboursé intégralement. Dans les autres villes du Bénin, la Livraison Express ne s''applique pas : comptez 48 à 72 h.', 'express rapide vite urgent aujourd''hui ce soir même jour demain lendemain heure limite avant 20h 20 heures dimanche week-end weekend quand recevoir reçu livré quand en retard retard pas encore arrivé délai livraison express cotonou calavi godomey', true),
  ('5eed0000-0000-4000-8000-000000000002', 'Livraison', 'Zones et délais de livraison', 'Nous livrons à domicile à Cotonou, à Abomey-Calavi et dans les autres villes du Bénin. À Cotonou et Calavi (Livraison Express) : le jour même pour une commande passée avant 20 h, sinon le lendemain, 7 j/7, dimanche compris. Dans les autres villes du Bénin, comptez 48 à 72 h. Nous ne livrons pas hors du Bénin pour le moment. Nous n''avons pas de boutique physique et il n''y a pas de retrait sur place : chaque commande est livrée à l''adresse que vous indiquez. Le livreur vous appelle avant d''arriver.', 'zone zones ville villes délai délais combien de jours livrer livrez-vous livreur zem moto domicile adresse quartier parakou porto-novo bohicon abomey ouidah natitingou lokossa djougou kandi savè dassa allada hors bénin étranger togo nigeria lomé retrait récupérer passer chercher', true),
  ('5eed0000-0000-4000-8000-000000000003', 'Livraison', 'Frais de livraison et livraison offerte', 'À Cotonou et Abomey-Calavi, la livraison coûte 1 000 F et elle est offerte dès 15 000 F d''achat. Dans les autres villes du Bénin, elle coûte 2 500 F : la livraison offerte ne concerne que la zone Cotonou et Calavi. Les frais de livraison s''ajoutent au prix des produits et vous les voyez avant de valider votre commande. Les prix sont en francs CFA, toutes taxes comprises, et vous payez le prix affiché au moment où vous commandez.', 'frais prix coût combien coûte tarif livraison gratuite offerte gratuit franco montant minimum 15000 1000 2500 fcfa francs cfa taxes ttc payer la livraison', true),
  ('5eed0000-0000-4000-8000-000000000004', 'Livraison', 'Le jour de la livraison', 'Nous vous envoyons une confirmation sur WhatsApp avec le créneau de livraison, puis le livreur vous appelle avant d''arriver. Si vous payez à la réception, préparez le montant en espèces ou payez par Mobile Money au livreur. Pour un paiement à la livraison, l''heure limite de la Livraison Express s''applique à l''heure de cette confirmation WhatsApp. Si vous n''êtes pas là, nous vous proposons une nouvelle livraison ; après deux tentatives sans succès, nous pouvons annuler la commande. Gardez votre téléphone joignable le jour de la livraison.', 'jour livraison livreur zem appel appeler téléphone créneau heure confirmation whatsapp absent pas là reporter reprogrammer autre jour tentative préparer monnaie espèces cash momo porte', true),
  ('5eed0000-0000-4000-8000-000000000005', 'Paiement', 'Moyens de paiement', 'Les moyens de paiement disponibles sont ceux affichés au moment de valider votre commande : si un moyen n''y apparaît pas, il n''est pas disponible pour le moment. Selon ce qui est affiché, vous pouvez payer à la livraison, en espèces ou par Mobile Money au livreur, ou en ligne par Mobile Money (MTN MoMo, Moov Money, Celtiis Cash). Le paiement par carte bancaire n''est pas proposé pour l''instant. Si vous payez à la livraison, nous confirmons d''abord votre commande sur WhatsApp. Le montant total, livraison comprise, s''affiche avant que vous validiez la commande. Nous ne vous demanderons jamais votre code secret.', 'payer paiement moyens momo mtn moov flooz celtiis mobile money espèces cash liquide à la livraison à la réception porte carte bancaire visa mastercard en ligne comment payer accepté acceptez', true),
  ('5eed0000-0000-4000-8000-000000000006', 'Paiement', 'Paiement sécurisé et code secret', 'Ni notre équipe ni nos livreurs ne vous demanderont votre code secret Mobile Money, ni par téléphone, ni sur WhatsApp, ni par SMS, ni en personne. Si quelqu''un vous le demande en se présentant comme Wá xɔ, ne le donnez pas et prévenez-nous sur notre numéro WhatsApp affiché en bas du site. Pour un paiement à la livraison, vous payez le livreur seulement quand vous recevez le colis. Les paiements en ligne, quand ils sont proposés, passent par un prestataire de paiement agréé : Wá xɔ n''a jamais accès à vos codes secrets. Les échanges avec le site sont chiffrés (HTTPS).', 'sécurisé sécurité sûr confiance arnaque fraude code secret pin mot de passe fedapay prestataire chiffré https protégé données bancaires faux numéro escroquerie appel suspect', true),
  ('5eed0000-0000-4000-8000-000000000007', 'Livraison', 'Suivre sa commande', 'Après votre commande, un numéro de commande (WX-…) s''affiche et vous recevez une confirmation par WhatsApp ou SMS. Pour suivre votre commande, ouvrez la page Suivi de commande et saisissez ce numéro avec l''e-mail ou le téléphone utilisé pour commander. Si vous avez commandé avec un compte, le statut est aussi visible dans votre espace client. L''assistant ne consulte pas les commandes. Pour une question sur une commande en cours, écrivez-nous sur WhatsApp en indiquant votre numéro WX-…, c''est le plus rapide.', 'suivre suivi où est ma commande statut état numéro wx colis en route expédiée livrée arrivée en retard retard toujours rien pas reçu tracking confirmation sms', true),
  ('5eed0000-0000-4000-8000-000000000008', 'Compte', 'Commander avec ou sans compte', 'Vous n''avez pas besoin de compte pour commander : vous indiquez vos coordonnées de livraison, vous choisissez un moyen de paiement et vous validez. Sans compte, vous suivez votre commande avec son numéro (WX-…) depuis la page Suivi de commande. Un compte sert à suivre vos commandes, à retrouver vos informations de livraison et à donner votre avis sur les produits. Vous modifiez vos informations depuis votre espace. Pour demander la suppression de votre compte, écrivez au service client. Le compte reste facultatif.', 'compte inscription inscrire créer un compte sans compte invité connexion se connecter mot de passe oublié espace client profil obligatoire supprimer mon compte modifier mes informations', true),
  ('5eed0000-0000-4000-8000-000000000009', 'Autre', 'Modifier ou annuler une commande', 'Pour modifier ou annuler une commande, écrivez-nous au plus vite sur notre numéro WhatsApp affiché en bas du site, avec votre numéro de commande (WX-…) : l''équipe vous dit ce qui est encore possible. L''assistant ne peut pas modifier une commande. Si nous vous prévenons d''un retard de livraison, vous pouvez annuler et être remboursé intégralement. Nous pouvons aussi annuler une commande si les informations sont incomplètes, si un produit n''est plus disponible ou en cas de problème de paiement ; si vous aviez déjà payé, vous êtes alors remboursé intégralement.', 'modifier changer annuler annulation commande erreur adresse changer d''adresse quantité ajouter retirer produit me suis trompé rembourser remboursement intégral retard', true),
  ('5eed0000-0000-4000-8000-000000000010', 'Retours', 'Retours et échanges', 'Vous avez 7 jours après la réception pour demander un échange ou un remboursement, sans avoir à vous justifier, pour un produit non utilisé, complet et dans son emballage d''origine. Écrivez-nous sur WhatsApp ou via le formulaire de contact, avec votre numéro de commande. À Cotonou et Calavi, notre livreur passe reprendre le produit chez vous. Ailleurs au Bénin, nous vous expliquons comment nous l''envoyer ; pour un simple changement d''avis, les frais de renvoi sont à votre charge. Les produits d''hygiène ou de soin descellés ne sont pas repris, sauf défaut. Après vérification du produit, nous vous l''échangeons ou nous vous remboursons au plus tard 7 jours après l''avoir reçu, par le moyen de paiement utilisé (par Mobile Money si vous avez payé à la livraison).', 'retour retourner rendre renvoyer échanger échange remboursement rembourser changer d''avis plus envie pas satisfait taille couleur délai 7 jours emballage hygiène frais de retour qui paie', true),
  ('5eed0000-0000-4000-8000-000000000011', 'Retours', 'Produit défectueux ou erreur de commande', 'Si un produit a un défaut ou ne correspond pas à votre commande, écrivez-nous sur WhatsApp ou via le formulaire de contact, avec une photo et votre numéro de commande (WX-…) ; pour un défaut visible ou une erreur de produit, faites-le dans les 48 h qui suivent la réception. Nous l''échangeons ou nous vous le remboursons, et les frais de retour sont à notre charge, où que vous soyez au Bénin. Si un défaut apparaît plus tard, à l''usage, écrivez-nous aussi : l''équipe examine votre demande. Un produit d''hygiène descellé est lui aussi repris s''il a un défaut.', 'défectueux défaut cassé abîmé endommagé ne marche pas ne fonctionne pas panne en panne mauvais produit erreur pas le bon produit manquant incomplet non conforme photo garantie frais de retour', true),
  ('5eed0000-0000-4000-8000-000000000012', 'Boutique', 'Horaires et contact', 'Notre équipe vous répond sur WhatsApp 7 j/7, de 8 h à 20 h : écrivez-nous sur notre numéro WhatsApp affiché en bas du site. Vous pouvez aussi utiliser le formulaire de contact du site. L''assistant IA du site répond 24 h/24 aux questions courantes ; pour le reste, il vous oriente vers l''équipe, qui vous répond de 8 h à 20 h. Pour une commande en cours, WhatsApp est le plus rapide : indiquez votre numéro de commande (WX-…). Nous n''avons pas de boutique physique, donc pas d''accueil sur place.', 'horaires horaire heure heures à quelle heure joignable joignables répondez-vous ouverture ouvert fermé dimanche contact contacter joindre appeler numéro téléphone whatsapp e-mail mail service client équipe humain conseiller parler à quelqu''un adresse magasin', true),
  ('5eed0000-0000-4000-8000-000000000013', 'Boutique', 'Les packs', 'Un pack réunit des produits choisis pour aller ensemble, vendus à un prix plus doux que séparément. Sur la page du pack, le prix du pack est affiché face à la somme des produits achetés à l''unité : vous voyez l''économie. Vous commandez le pack en un clic, nous emballons tout ensemble et nous livrons un seul colis. Si un des produits du pack n''est plus en stock, le pack est indiqué épuisé ; les produits sont aussi vendus à l''unité dans le catalogue. Les packs disponibles sont sur la page Packs du site.', 'pack packs lot lots ensemble coffret combo kit offre groupée économie économiser moins cher réduction un seul colis', true),
  ('5eed0000-0000-4000-8000-000000000014', 'Boutique', 'Promotions et campagnes', 'Les promotions sont affichées directement sur le site : le prix réduit apparaît à côté du prix normal barré, et c''est ce prix que vous payez, sans code à saisir. Certaines offres font partie d''une campagne à durée limitée, dont la date de fin est indiquée sur le site. Les produits en promotion sont regroupés dans la rubrique Promotions. Vous payez le prix affiché au moment où vous commandez. Pour être prévenu des arrivages et des promos, inscrivez-vous à la newsletter : un message par semaine au maximum, désinscription en un clic.', 'promo promos promotion promotions réduction solde soldes rabais remise code promo bon de réduction coupon campagne offre limitée black friday tabaski noël prix barré moins cher newsletter', true),
  ('5eed0000-0000-4000-8000-000000000015', 'Boutique', 'Avis clients', 'Sur les fiches produit, seuls les clients inscrits peuvent publier un avis, un par produit, et le badge « Achat vérifié » signale un produit reçu par une commande Wá xɔ. Vous pouvez aussi donner votre avis sur la boutique (livraison, service, emballage, articles reçus) depuis la page « Donner mon avis » : c''est réservé aux clients qui ont reçu une commande, et l''avis est publié après relecture. Nous ne modifions jamais le contenu d''un avis ; nous pouvons masquer un avis injurieux, publicitaire ou qui contient des données personnelles de tiers. Les avis ne sont pas rémunérés.', 'avis commentaire commentaires note étoiles témoignage noter donner mon avis laisser un avis achat vérifié client vérifié faux avis fiable', true),
  ('5eed0000-0000-4000-8000-000000000016', 'Boutique', 'Qui sommes-nous', 'Wá xɔ veut dire « venez acheter » en fon. Nous sommes une boutique en ligne basée à Cotonou : nous choisissons des objets du quotidien pour la maison, la cuisine, la beauté, le bureau, la tech et le voyage, nous les stockons nous-mêmes à Cotonou et nous les livrons chez vous. Le stock affiché est réel et mis à jour à chaque commande. Nous n''avons pas de boutique physique : chaque commande part directement de notre stock. Sur Google, vous pouvez aussi nous trouver sous le nom « Waxo ».', 'qui êtes-vous qui sommes-nous à propos boutique magasin entreprise wa xo waxo fon signification nom stock réel en stock disponible cotonou bénin sérieux fiable', true),
  ('5eed0000-0000-4000-8000-000000000017', 'Compte', 'Confidentialité et vos informations', 'Vos informations (nom, téléphone, adresse de livraison, e-mail si vous le donnez) servent notamment à préparer, livrer et suivre vos commandes et à vous répondre ; elles ne sont jamais vendues. Tout est détaillé dans notre politique de confidentialité, en bas du site : informations collectées, utilisations, destinataires, durée de conservation et vos droits. Les messages écrits à l''assistant sont transmis au fournisseur de sa technologie d''intelligence artificielle pour générer les réponses : n''y indiquez jamais de mot de passe, de code Mobile Money ni de numéro de carte. Le site utilise aussi le pixel de Meta pour mesurer nos publicités ; vous pouvez le refuser à tout moment depuis « Gérer mes cookies », en bas du site. Pour accéder à vos informations, les corriger, vous opposer à leur utilisation ou demander leur suppression, écrivez à l''adresse indiquée dans la politique ; vous pouvez aussi saisir l''APDP (apdp.bj).', 'confidentialité vie privée informations coordonnées numéro adresse cookies newsletter désinscrire supprimer effacer accès rectifier qui voit mes informations vendre revendre cookies pixel meta refuser opposition apdp', true)
