-- 0021_kb_seed.sql : base de connaissances réelle de l'assistant (17 fiches, en français), 2026-10-13.
-- Source lisible : docs/kb/fiches-2026-10-13.md. Faits : brief RAG du 2026-10-13, réglages en base, textes validés
-- (FAQ, pages légales, pages CMS 0013/0014/0017). UUID fixes (préfixe 5eed) : rejouable sans doublon.
-- Rejouer la migration remet le texte de CES fiches à la version ci-dessous (une modification faite depuis l'admin
-- sur l'une d'elles serait écrasée) ; elle ne touche jamais aux autres fiches ni à la case « active » d'une fiche existante.
-- Les chiffres (20 h, 1 000 F, 2 500 F, 15 000 F, 7 jours) sont ceux des réglages au 2026-10-13 : à mettre à jour
-- dans l'admin si les réglages changent (les réponses sur la livraison, le paiement et les retours reprennent déjà
-- les valeurs des réglages, voir src/lib/assistant/kb.ts).

alter table public.kb enable row level security;

on conflict (id) do update set
  tag = excluded.tag,
  title = excluded.title,
  text = excluded.text,
  keywords = excluded.keywords;
